#include <acl-lib/fiber/lib_fiber.hpp>
#include <acl-lib/fiber/go_fiber.hpp>
int main(int argc, char**) {
    acl::acl_cpp_init();
    go [argc] {
        volatile char bytes[16];
        volatile int index = argc + 15;
        bytes[index] = 42;
    };
    acl::fiber::schedule();
